//! Parity between the transcribe command in `voxr_narrate`
//! ([`plan_transcribe`], [`narration_words`], the lines and the video
//! timeline) and the skill's own `transcribeCmd`.
//!
//! The fixture (`tests/fixtures/narration_command_transcribe_oracle.json`)
//! is checked in and was generated by
//! `tests/tools/narration_oracle/command_transcribe.mjs`, which runs
//! `transcribeCmd` from video.mjs, and the part of `main` that picks its
//! manifest, with `transcribe()` stubbed to return the scenario's
//! recognized words. Each scenario here replays the same files and flags
//! with the same words, and compares every recognizer call, every printed
//! line, the exit code or the error, and every file left.

use std::path::Path;

use serde::Deserialize;
use serde_json::{Map, Value, json};
use voxr_narrate::{
    CommandError, HeardWord, TranscribeFlags, Transcribed, check_narration, narration_lines,
    narration_words, overrun_line, pcm16_wav, plan_transcribe, probed_duration, read_wav_file,
    transcribe_model, write_narration, write_video_timeline,
};

mod common;
use common::signals::fnv1a_bytes;
use common::take_files::{OpJson, render_json};
use common::{assert_oracle_current, load_json};

const FIXTURE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/fixtures/narration_command_transcribe_oracle.json"
);
const ORACLE: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/tools/narration_oracle/command_transcribe.mjs"
);

#[derive(Debug, Deserialize)]
struct Fixture {
    rate: u32,
    scenarios: Vec<Scenario>,
}

#[derive(Debug, Deserialize)]
struct Signal {
    n: usize,
    ops: Vec<OpJson>,
}

#[derive(Debug, Deserialize)]
struct Scenario {
    name: String,
    audio: std::collections::BTreeMap<String, Signal>,
    files: Map<String, Value>,
    heard: std::collections::BTreeMap<String, Vec<HeardWord>>,
    opts: Value,
    #[serde(default)]
    config: Value,
    output: Output,
}

#[derive(Debug, Deserialize)]
struct Output {
    calls: Vec<Value>,
    lines: Vec<LineJson>,
    code: Option<i32>,
    failure: Option<Failure>,
    files: Vec<FileJson>,
}

#[derive(Debug, Deserialize, PartialEq)]
struct LineJson {
    stream: String,
    text: String,
}

#[derive(Debug, Deserialize)]
struct Failure {
    input: bool,
    message: String,
}

#[derive(Debug, Deserialize, PartialEq)]
struct FileJson {
    path: String,
    text: Option<String>,
    bytes: Option<String>,
}

fn normalize(text: &str, dir: &Path) -> String {
    text.replace(&dir.to_string_lossy().into_owned(), "<dir>")
}

fn flags(opts: &Value) -> TranscribeFlags {
    let text = |k: &str| opts[k].as_str().map(str::to_string);
    TranscribeFlags {
        files: opts["rest"]
            .as_array()
            .map(|r| {
                r.iter()
                    .filter_map(|s| s.as_str().map(str::to_string))
                    .collect()
            })
            .unwrap_or_default(),
        model: text("model"),
        language: text("language"),
        script: text("script"),
        manifest: text("manifest"),
        // A case without "manifest" ran with it undefined: `--manifest`
        // given last, with no value.
        manifest_missing: opts.get("manifest").is_none(),
    }
}

fn files(root: &Path) -> Vec<FileJson> {
    let mut out = Vec::new();
    let mut dirs = vec![root.to_path_buf()];
    while let Some(d) = dirs.pop() {
        for entry in
            std::fs::read_dir(&d).unwrap_or_else(|e| panic!("listing {}: {e}", d.display()))
        {
            let path = entry.unwrap_or_else(|e| panic!("{e}")).path();
            if path.is_dir() {
                dirs.push(path);
                continue;
            }
            let rel = path
                .strip_prefix(root)
                .unwrap_or_else(|e| panic!("{e}"))
                .components()
                .map(|c| c.as_os_str().to_string_lossy().into_owned())
                .collect::<Vec<_>>()
                .join("/");
            let bytes = std::fs::read(&path).unwrap_or_else(|e| panic!("{e}"));
            out.push(if rel.ends_with(".wav") {
                FileJson {
                    path: rel,
                    text: None,
                    bytes: Some(fnv1a_bytes(&bytes)),
                }
            } else {
                FileJson {
                    path: rel,
                    text: Some(normalize(&String::from_utf8_lossy(&bytes), root)),
                    bytes: None,
                }
            });
        }
    }
    out.sort_by(|a, b| a.path.cmp(&b.path));
    out
}

fn run(s: &Scenario, rate: u32) {
    let root = tempfile::tempdir().unwrap_or_else(|e| panic!("{e}"));
    let dir = root.path();
    for (path, content) in &s.files {
        let p = dir.join(path);
        if let Some(parent) = p.parent() {
            std::fs::create_dir_all(parent).unwrap_or_else(|e| panic!("{e}"));
        }
        std::fs::write(&p, content.as_str().unwrap_or_default()).unwrap_or_else(|e| panic!("{e}"));
    }
    for (path, sig) in &s.audio {
        let x = render_json(sig.n, &sig.ops);
        std::fs::write(
            dir.join(path),
            pcm16_wav(&x, rate).unwrap_or_else(|e| panic!("{e}")),
        )
        .unwrap_or_else(|e| panic!("{e}"));
    }
    let f = flags(&s.opts);
    let configured = s.config["asr"]["model"].as_str();
    let mut lines: Vec<String> = Vec::new();
    let mut calls = Vec::new();
    let mut probe = |p: &Path| read_wav_file(p).map(|t| probed_duration(t.samples.len(), t.rate));
    let outcome = (|| -> Result<i32, CommandError> {
        let plan = plan_transcribe(&f, dir, &mut probe)?;
        let model = transcribe_model(f.model.as_deref(), f.language.as_deref(), configured);
        for n in &plan.narrations {
            check_narration(n)?;
            calls.push(json!({
                "file": normalize(&n.file.to_string_lossy(), dir),
                "model": model,
                "language": f.language,
            }));
            let take = read_wav_file(&n.file).map_err(|e| CommandError::Failed(e.to_string()))?;
            let name = n
                .file
                .file_name()
                .map(|x| x.to_string_lossy().into_owned())
                .unwrap_or_default();
            let t = Transcribed {
                words: s.heard.get(&name).cloned().unwrap_or_default(),
                looped: false,
                duration: (take.samples.len() as f64 / f64::from(take.rate) * 1000.0).round()
                    / 1000.0,
            };
            let words = narration_words(n, &model, t, &take.samples)?;
            let out = write_narration(&plan.out_dir, n, &words)?;
            lines.extend(narration_lines(n, &words, &out));
        }
        if let (true, Some(m)) = (plan.timeline, &plan.manifest) {
            lines.push(write_video_timeline(&m.narration)?.1);
        }
        if let Some(line) = plan
            .manifest
            .as_ref()
            .and_then(|m| overrun_line(m.voiceover_overrun))
        {
            lines.push(line);
        }
        Ok(0)
    })();
    let name = &s.name;
    assert_eq!(calls, s.output.calls, "recognizer calls, scenario {name}");
    let got: Vec<LineJson> = lines
        .iter()
        .map(|l| LineJson {
            stream: "out".to_string(),
            text: normalize(l, dir),
        })
        .collect();
    assert_eq!(got, s.output.lines, "lines, scenario {name}");
    match (&outcome, &s.output.failure) {
        (Ok(code), None) => assert_eq!(Some(*code), s.output.code, "exit code, scenario {name}"),
        (Err(e), Some(want)) => {
            assert_eq!(
                matches!(e, CommandError::Input(_)),
                want.input,
                "error kind, scenario {name}: {e}"
            );
            assert_eq!(
                normalize(e.message(), dir),
                want.message,
                "error, scenario {name}"
            );
        }
        (got, want) => panic!("scenario {name}: got {got:?}, want {want:?}"),
    }
    assert_eq!(files(dir), s.output.files, "files, scenario {name}");
}

#[test]
fn transcribe_command_matches_javascript_on_every_scenario() {
    let fixture: Fixture = load_json(Path::new(FIXTURE));
    assert!(!fixture.scenarios.is_empty(), "fixture must not be empty");
    for s in &fixture.scenarios {
        run(s, fixture.rate);
    }
}

#[test]
fn transcribe_command_oracle_fixture_is_current() {
    assert_oracle_current(ORACLE, FIXTURE);
}
